from rdkit import Chem

# Parse the input SMILES
smiles = "CC(C)(C(=O)NCC1CC1)c1ccc(S(=O)(=O)/C=C/C#N)cc1"
mol = Chem.MolFromSmiles(smiles)

if mol:
    print("Molecule parsed successfully")
    print(f"Number of atoms: {mol.GetNumAtoms()}")

    # Find amide bonds
    for bond in mol.GetBonds():
        if bond.GetBondType() == Chem.BondType.AMIDE or (bond.GetBeginAtom().GetAtomicNum() == 6 and bond.GetEndAtom().GetAtomicNum() == 7):
            begin = bond.GetBeginAtom()
            end = bond.GetEndAtom()
            print(f"Bond between C{begin.GetIdx()} and N{end.GetIdx()}")

    # Print atom types
    for atom in mol.GetAtoms():
        print(f"Atom {atom.GetIdx()}: {atom.GetSymbol()} hybridization={atom.GetHybridization()}")

    # Try to identify the amide linkage
    # Look for C(=O)N pattern
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() == 6 and atom.GetTotalNumHs() == 0:
            neighbors = [n.GetIdx() for n in atom.GetNeighbors()]
            has_double_o = False
            has_n_neighbor = False
            for n_idx in neighbors:
                n_atom = mol.GetAtomWithIdx(n_idx)
                bond = mol.GetBondBetweenAtoms(atom.GetIdx(), n_idx)
                if n_atom.GetAtomicNum() == 8 and bond.GetBondType() == Chem.BondType.DOUBLE:
                    has_double_o = True
                if n_atom.GetAtomicNum() == 7:
                    has_n_neighbor = True
            if has_double_o and has_n_neighbor:
                print(f"Found carbonyl carbon at index {atom.GetIdx()}")
else:
    print("Failed to parse molecule")
